def build():
    s = open(SRC, encoding='utf-8').read()
    missing = []
    for a, b in PAIRS:
        if a.startswith('re:'):
            s2, n = re.subn(a[3:], b, s)
        else:
            n = s.count(a); s2 = s.replace(a, b)
        if not n: missing.append(a)
        s = s2
    if missing:
        sys.exit('Frases en español no encontradas (¿cambió index.html?):\n  ' + '\n  '.join(missing))
    os.makedirs(os.path.dirname(DST), exist_ok=True)
    open(DST, 'w', encoding='utf-8').write(s)
    print('VOO 40 (pt-BR) generado en', os.path.relpath(DST, ROOT))


if __name__ == '__main__':
    build()
